    public sealed partial class R23HandsWeapons
    {
        R24KnifePhysics knifePhysics;R24ItemAudio knifeAudio;AudioSource knifeWhoosh;bool knifeReady;
        bool IsMelee{get{return R24MeleeProfiles.ForId(ActiveWeaponId)!=null;}}
        public R24KnifeDiagnostics KnifeDiagnostics{get{var d=knifePhysics==null?new R24KnifeDiagnostics():knifePhysics.ReadDiagnostics();var owner=round==null?null:round.Melee;if(owner!=null){d.OwnerInstance=owner.InstanceId;d.OwnerFrames=owner.FrameCount;d.OwnerSuspensions=owner.SuspensionCount;d.OwnerHistory=owner.HistoryValid;d.OwnerRetired=owner.IsRetired;d.OwnerStatus=owner.LastFrameStatus;d.OwnerLastSuspension=owner.LastSuspension;}return d;}}public string KnifeLastBarrier{get;private set;}public Vector3 KnifeLastBarrierPoint{get;private set;}
        public int KnifeHullQueries{get{return knifePhysics==null?0:knifePhysics.HullQueries;}}public bool TryReadMeleeTargetCollider(int index,out Collider collider){collider=index<0||index>=targets.Count?null:targets[index].Body;return collider!=null;}
        public bool KnifeReady{get{return knifeReady;}}public long KnifeAcceptedContacts{get{return round==null||round.Melee==null?0:round.Melee.AcceptedContacts;}}public int KnifeLastSubsteps{get{return knifePhysics==null?0:knifePhysics.LastSubsteps;}}
