        public Vector3 KnifeLastContactPoint{get;private set;}public string KnifeLastContactTarget{get;private set;}public event Action<string,Vector3,float> MeleeContactAccepted;
        IEnumerator LoadKnifePresentation(){yield return visuals.Load("knife",weaponModels[17]);foreach(var renderer in weaponModels[17].GetComponentsInChildren<Renderer>(true))renderer.shadowCastingMode=ShadowCastingMode.Off;knifeAudio=new R24ItemAudio();knifeAudio.SetVolume(sfxVolume);yield return knifeAudio.Load("knife-swing");knifeWhoosh=knifeAudio.Voice(weapon,"Source knife deliberate swing",-13,15);knifePhysics=new R24KnifePhysics(content,Excluded,ResolveKnifeTarget,KnifeLineClear);knifeReady=true;}
        string ResolveKnifeTarget(Collider collider){foreach(var target in targets)if(target.Owns(collider))return target.TargetId;return MeleeWorldTargetId==null?null:MeleeWorldTargetId(collider);}
        bool KnifeLineClear(Vector3 from,Vector3 to,string target){var delta=to-from;if(delta.sqrMagnitude<.00001f)return true;foreach(var hit in Physics.RaycastAll(from,delta.normalized,delta.magnitude,(1<<0)|(1<<19),QueryTriggerInteraction.Ignore)){if(ImpactActorOrIgnored(hit.collider))continue;if(ResolveKnifeTarget(hit.collider)==target)continue;KnifeLastBarrier=hit.collider.name;KnifeLastBarrierPoint=hit.point;return false;}return true;}
        bool KnifeUsable{get{return knifeReady&&(ActiveWeaponId=="knife"||bladeReady)&&IsMelee&&FeedbackAllowed&&MeleeWorldInputAllowed!=null&&MeleeWorldInputAllowed();}}
        void RenderKnifePose(){if(weapon==null||weaponModels.Count<18)return;aimFilterReady=false;var q=weapon.rotation;var origin=weapon.position;weaponModels[selectedWeapon].SetPositionAndRotation(origin,q);displayedShot=new R23ShotPose(To(weapon.TransformPoint(From(R24KnifeRuntime.Grip))),To(q*Vector3.right),To(q*Vector3.up),To(q*Vector3.forward));muzzle.SetPositionAndRotation(From(displayedShot.Origin),q);displayedPoseValid=true;}
        void SyncKnifePresentation(){RenderKnifePose();if(gunFeedback!=null)gunFeedback.HideHeldPresentation();if(smawView!=null)smawView.Holster();SyncBladePresentation();if(!KnifeUsable&&knifeWhoosh!=null)knifeWhoosh.Stop();}
        bool TickKnife(float dt){KnifeLastBarrier=null;KnifeLastBarrierPoint=Vector3.zero;bool usable=KnifeUsable;round.AdvanceSmawWorld(dt,!usable);RenderKnifePose();UpdateBladeSupport(usable);if(knifePhysics==null||round.Melee==null)return false;var q=weapon.rotation;var blade=new R23ShotPose(To(weapon.position),To(q*Vector3.right),To(q*Vector3.up),To(q*Vector3.forward));var actor=new R23ShotPose(To(player.position),To(player.right),To(player.up),To(player.forward));int damage=knifePhysics.Sample(round.Melee,dt,usable,actor,blade,To(PrimaryTransform.position),To(head.transform.position),ApplyKnifeHit);var owner=round.Melee;PlayBladeWhoosh(owner);SampleBladeArt(dt,usable);if(!usable&&knifeWhoosh!=null)knifeWhoosh.Stop();if(owner.AcceptedContacts>0)ActiveFeedback.AcceptedShot(owner.AcceptedContacts,false);UpdateWeaponPresentation();foreach(var target in targets)target.Refresh(round);return damage>0;}
        bool ApplyKnifeHit(R24KnifeHit hit){KnifeLastContactPoint=hit.Point;KnifeLastContactTarget=hit.Entry.TargetId;bool applied=false,practice=false;ActiveBladeDamagePoint=hit.Point;try{foreach(var target in targets)if(target.TargetId==hit.Entry.TargetId){practice=true;var before=round.ReadTarget(target.TargetId);applied=round.ApplyKnifeContact(activeActionId,hit.Entry);var after=round.ReadTarget(target.TargetId);target.Refresh(round);if(applied&&TargetDamaged!=null)TargetDamaged(target.TargetId,false,before.Shield-after.Shield,before.Health-after.Health);break;}if(!practice)applied=round.Melee.ApplyContact(hit.Entry,delegate(string id,float amount){if(WorldHit==null||hit.Collider==null)return false;WorldHit(hit.Collider,amount);return true;});}finally{ActiveBladeDamagePoint=null;}if(gunFeedback!=null)gunFeedback.Impact(hit.Point,-hit.Direction,Time.unscaledTime);if(audioCues!=null)audioCues.Play("knife","hit",false);Pulse(primaryHand,.65f,.06f);if(MeleeContactAccepted!=null)MeleeContactAccepted(hit.Entry.TargetId,hit.Point,hit.Entry.Damage);return applied;}
    }
